'use strict';
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

async function runChatDemoSmoke(win, { output }) {
  const run = (fn, ...args) => win.webContents.executeJavaScript(`(${fn.toString()})(${args.map(arg => JSON.stringify(arg)).join(',')})`);
  const result = await run(async function exercise() {
    const $ = selector => document.querySelector(selector);
    const check = (condition, label) => { if (!condition) throw new Error(label); checks.push(label); };
    const checks = [];
    const change = (selector, value, type = 'input') => { const field = $(selector); field.value = value; field.dispatchEvent(new Event(type, { bubbles: true })); };
    const click = action => $(`[data-cd-action="${action}"]`).click();
    const input = text => change('.cd-input', text);
    const submit = () => $('.cd-composer').requestSubmit();
    const count = () => document.querySelectorAll('[data-cd-message]').length;
    const closeModal = () => click('close-modal');
    const project = { projectId: 'demo-a', name: '江湾项目 · 合成测试', currentMemberId: 'me', members: [{ id: 'me', name: '陈设计', role: 'designer' }, { id: 'lin', name: '林澜', role: 'project_manager' }, { id: 'zhao', name: '赵工', role: 'reviewer' }] };
    const original = JSON.stringify(project);
    const other = { ...project, projectId: 'demo-b', name: '海湾项目 · 合成测试' };
    window.__demoFixture = { project, other };
    aidesignChatDemo.mount($('#hubChatDemo'));
    aidesignChatDemo.setProject(project);
    aidesignChatDemo.setActive(true);
    check(count() === 4, 'four clearly marked synthetic messages');
    check($('.cd-demo-banner').textContent.includes('不写入项目'), 'demo persistence boundary visible');
    check(!$('#hubChatDemo').querySelector('select'), 'no topic/channel dropdown by default');
    const before = count();
    input('中文输入法未确认');
    $('.cd-input').dispatchEvent(new CompositionEvent('compositionstart', { bubbles: true }));
    $('.cd-input').dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true, cancelable: true }));
    check(count() === before, 'IME composition Enter does not send');
    $('.cd-input').dispatchEvent(new CompositionEvent('compositionend', { bubbles: true }));
    $('.cd-input').dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', keyCode: 229, bubbles: true, cancelable: true }));
    check(count() === before, 'IME keyCode 229 does not send');
    $('.cd-input').dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', shiftKey: true, bubbles: true, cancelable: true }));
    check(count() === before, 'Shift Enter does not send');
    input('独特关键词 <img src=x onerror="window.demoXss=1">');
    $('.cd-input').dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true, cancelable: true }));
    check(count() === before + 1 && $('.cd-input').value === '', 'Enter adds one local message and clears draft');
    check(!window.demoXss && !$('.cd-messages').querySelector('[onerror]') && $('.cd-messages').textContent.includes('<img src=x'), 'message HTML is rendered as text');
    const ownId = document.querySelectorAll('[data-cd-message]')[before].dataset.cdMessage;
    $(`[data-cd-reply="${ownId}"]`).click();
    check(!$('.cd-reply-preview').hidden, 'quote preview appears');
    input('引用回复测试'); submit();
    check(document.querySelectorAll('.cd-quoted').length === 1, 'quote links to existing local message');
    click('search');
    change('[data-cd-search]', '独特关键词');
    check(document.querySelectorAll('.cd-search-result').length === 1, 'history keyword filter');
    change('[data-cd-search-member]', 'lin', 'change');
    check(document.querySelectorAll('.cd-search-result').length === 0, 'history member filter');
    change('[data-cd-search-member]', '', 'change'); change('[data-cd-search]', '');
    change('[data-cd-search-type]', 'image', 'change');
    check(document.querySelectorAll('.cd-search-result').length === 1, 'history image type filter');
    change('[data-cd-search-type]', 'file', 'change');
    check(document.querySelectorAll('.cd-search-result').length === 1, 'history file type filter');
    $('.cd-search-result').click();
    check($('.cd-panel').hidden && !!$('.cd-highlight'), 'search result locates message');
    click('members');
    check(document.querySelectorAll('.cd-person').length === 4, 'member grid includes demo assistant');
    $('[data-cd-person="lin"]').click();
    change('[data-cd-role]', '设计总监', 'change'); $('[data-cd-save-role="lin"]').click();
    check($('[data-cd-person="lin"]').textContent.includes('设计总监'), 'role change is visible in demo');
    check(JSON.stringify(project) === original, 'role demo does not mutate supplied project data');
    click('close-panel');
    click('voice');
    check($('.cd-modal-root').textContent.includes('不会访问麦克风'), 'voice clearly labeled simulation');
    click('sample-voice');
    check($('.cd-input').value.includes('业主电话') && count() === before + 2, 'voice sample populates editable unsent draft');
    input('');
    click('screenshot');
    check($('.cd-modal-root').textContent.includes('不会读取你的屏幕'), 'screenshot clearly labeled simulation');
    click('sample-screenshot');
    check(document.querySelectorAll('.cd-pending').length === 1, 'screenshot sample attaches only a local asset');
    $('.cd-pending [data-cd-file]').click(); check(!!$('.cd-image-preview'), 'image preview opens'); closeModal();
    $('.cd-pending [data-cd-remove]').click();
    const fileInput = $('.cd-file-input');
    fileInput.click = () => {}; // Do not open the host OS file picker in automation.
    const transfer = new DataTransfer(); transfer.items.add(new File(['synthetic PDF'], '仅本机测试.pdf', { type: 'application/pdf' }));
    click('file'); fileInput.files = transfer.files; fileInput.dispatchEvent(new Event('change', { bubbles: true }));
    check($('.cd-attachments').textContent.includes('仅本机测试.pdf'), 'selected file becomes a local draft card');
    const bytes = Uint8Array.from(atob('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jc1sAAAAASUVORK5CYII='), c => c.charCodeAt(0));
    const imageTransfer = new DataTransfer(); imageTransfer.items.add(new File([bytes], '粘贴图片.png', { type: 'image/png' }));
    $('.cd-input').dispatchEvent(new ClipboardEvent('paste', { clipboardData: imageTransfer, bubbles: true, cancelable: true }));
    check(document.querySelectorAll('.cd-pending').length === 2, 'pasted image attaches without clipboard permission');
    $('.cd-pending .cd-image-card').click();
    const image = $('.cd-image-preview'); await image.decode();
    check(image.naturalWidth === 1 && image.src.startsWith('blob:'), 'local image preview uses renderer-only blob'); closeModal();
    input('待发草稿仅项目A');
    aidesignChatDemo.setProject(other);
    check($('.cd-input').value === '' && $('.cd-attachments').hidden && !$('.cd-messages').textContent.includes('独特关键词'), 'project switch isolates drafts attachments and messages');
    aidesignChatDemo.setProject(project);
    check($('.cd-input').value === '待发草稿仅项目A' && document.querySelectorAll('.cd-pending').length === 2, 'return to project restores memory-only draft and attachments');
    aidesignChatDemo.setProject({ ...project, currentMemberId: 'lin' });
    check($('.cd-input').value === '' && $('.cd-attachments').hidden && !$('.cd-messages').textContent.includes('独特关键词'), 'member identity switch isolates draft and messages');
    aidesignChatDemo.setProject(project);
    check($('.cd-input').value === '待发草稿仅项目A', 'return to identity restores its draft');
    submit();
    check($('.cd-messages').textContent.includes('仅本机测试.pdf') && $('.cd-attachments').hidden, 'sending attachments stays in local messages');
    click('file');
    aidesignChatDemo.setProject(other);
    fileInput.files = transfer.files; fileInput.dispatchEvent(new Event('change', { bubbles: true }));
    check($('.cd-attachments').hidden, 'late file picker result cannot attach to another project');
    aidesignChatDemo.setProject(project);
    const scope = { projectId: project.projectId, memberId: project.currentMemberId };
    input('@DesignHub 业主可能把汇报改到周五，暂定。'); submit();
    let candidate = aidesignContextReviewDemo.snapshot(scope).items.at(-1);
    check(candidate.status === 'needs_clarification' && !!$(`[data-cd-clarify="${candidate.id}"]`), 'uncertain mention creates linked clarification card');
    check(!$('[data-cd-review-approve]') && !$('[data-cd-approve]'), 'group has no approval action');
    input('已确认：这是一条没有引用的普通聊天。'); submit();
    check(aidesignContextReviewDemo.snapshot(scope).items.length === 1 && aidesignContextReviewDemo.snapshot(scope).items[0].status === 'needs_clarification', 'ordinary next message is not mistaken for clarification');
    $(`[data-cd-clarify="${candidate.id}"]`).click();
    input('也许周五，仍待确认。'); submit();
    check(aidesignContextReviewDemo.snapshot(scope).items[0].status === 'needs_clarification', 'ambiguous linked answer remains unresolved');
    $(`[data-cd-clarify="${candidate.id}"]`).click();
    input('已确认：周五下午两点汇报，由林澜负责。'); submit();
    check(aidesignContextReviewDemo.snapshot(scope).items[0].status === 'pending', 'explicit linked answer becomes pending');
    aidesignContextReviewDemo.review({ ...scope, id: candidate.id, decision: 'approve' });
    check($(`[data-cd-review-card="${candidate.id}"]`).textContent.includes('已进入演示上下文'), 'approved event refreshes group receipt');
    input('@DesignHub 已确定入口采用方案二，周四完成模型。'); submit();
    const rejected = aidesignContextReviewDemo.snapshot(scope).items.at(-1);
    aidesignContextReviewDemo.review({ ...scope, id: rejected.id, decision: 'reject' });
    check($(`[data-cd-review-card="${rejected.id}"]`).textContent.includes('已退回') && aidesignContextReviewDemo.snapshot(scope).approved.length === 1, 'rejection receipt never enters approved context');
    aidesignChatDemo.setProject(other);
    check(aidesignContextReviewDemo.snapshot({ ...scope, projectId: other.projectId }).items.length === 0 && !$('.cd-review-card'), 'review candidates isolated between projects');
    aidesignChatDemo.setProject({ ...project, currentMemberId: 'lin' });
    check(aidesignContextReviewDemo.snapshot({ ...scope, memberId: 'lin' }).items.length === 0 && !$('.cd-review-card'), 'review candidates isolated between members');
    aidesignChatDemo.setProject(project);
    $(`[data-cd-extract="${ownId}"]`).click();
    check($('.cd-modal-root').textContent.includes('不写入任务'), 'extract preview states no project write'); click('extract-done');
    const drag = new DataTransfer(); drag.items.add(new File(['draft'], '拖入文件.txt', { type: 'text/plain' }));
    $('#hubChatDemo').dispatchEvent(new DragEvent('drop', { dataTransfer: drag, bubbles: true, cancelable: true }));
    check($('.cd-attachments').textContent.includes('拖入文件.txt'), 'drag-drop file preview');
    input('关闭后不能发送'); const previous = count();
    aidesignChatDemo.setActive(false); submit();
    check(count() === previous && $('#hubChatDemo').inert, 'inactive demo cannot send');
    aidesignChatDemo.setActive(true); input(''); $('.cd-pending [data-cd-remove]').click();
    aidesignChatDemo.setView('知识中心');
    check($('.cd-messages').textContent.includes('独特关键词'), 'page navigation keeps project conversation');
    click('members');
    return { checks, assertionCount: checks.length };
  });
  await new Promise(resolve => setTimeout(resolve, 100));
  fs.writeFileSync(path.join(output, 'demo-wide.png'), (await win.webContents.capturePage()).toPNG());
  for (const width of [460, 340]) {
    win.setSize(width, 820);
    await new Promise(resolve => setTimeout(resolve, 100));
    const dimensions = await run(function dimensions() {
      const root = document.querySelector('#hubChatDemo');
      return { viewport: window.innerWidth, document: document.documentElement.scrollWidth, root: root.scrollWidth, client: root.clientWidth };
    });
    assert(dimensions.document <= dimensions.viewport + 1 && dimensions.root <= dimensions.client + 1, `Horizontal overflow at ${width}: ${JSON.stringify(dimensions)}`);
    result.checks.push(`no horizontal overflow at ${width}px`);
    fs.writeFileSync(path.join(output, `demo-${width}px.png`), (await win.webContents.capturePage()).toPNG());
  }
  result.assertionCount = result.checks.length;
  return result;
}
module.exports = { runChatDemoSmoke };
